7	 * name contains this marker are in-progress writes, not finished blobs, so
8	 * `listBlobs` must skip them and they must never be reachable through a
9	 * `key` a client controls.
10	 */
11	const TEMP_FILE_MARKER = ".syncbox-tmp-";
