28	/**
29	 * Resolves `key` to an absolute path on disk, guaranteed to stay inside `dataDir`.
30	 * Containment is checked on the *resolved* path rather than by scanning for ".."
31	 * substrings, so it also catches indirect escapes (e.g. "a/../../etc/passwd").
32	 */
33	export function keyToPath(dataDir: string, key: string): string {
34	  if (key.length === 0) {
35	    throw new InvalidKeyError("key must not be empty");
36	  }
37	  if (key.includes("\0")) {
38	    throw new InvalidKeyError("key must not contain a null byte");
39	  }
40	  if (!isWellFormed(key)) {
41	    throw new InvalidKeyError("key is not a well-formed string");
42	  }
43	  if (isAbsolute(key)) {
44	    throw new InvalidKeyError("key must not be an absolute path");
45	  }
46	
47	  const root = resolve(dataDir);
48	  const target = resolve(root, key);
49	  const rel = relative(root, target);
50	
51	  if (rel === "" || rel === ".." || rel.startsWith(`..${sep}`) || isAbsolute(rel)) {
52	    throw new InvalidKeyError("key escapes the storage root");
53	  }
54	
55	  return target;
56	}
57	
58	function isWellFormed(value: string): boolean {
59	  return Buffer.from(value, "utf8").toString("utf8") === value;
60	}
61	
62	export async function putBlob(
63	  dataDir: string,
64	  key: string,
65	  body: Buffer,
66	): Promise<PutResult> {
67	  const filePath = keyToPath(dataDir, key);
68	
69	  // Structural validation (in keyToPath above) can't catch every way a key
70	  // is unusable — some byte sequences are well-formed UTF-8 and stay inside
71	  // the storage root, yet the underlying filesystem/OS still refuses to
72	  // create a file or directory with that name (encoding restrictions,
73	  // reserved characters, length limits, ...), surfacing as an EIO/ENOENT/
74	  // EILSEQ-style error out of mkdir/writeFile/rename. From the API's point
75	  // of view that's just an unwritable key, not a server fault, so any
76	  // failure in this disk-write pipeline is reported the same way structural
77	  // rejection is: 400 via InvalidKeyError, never an uncaught 500.
78	  try {
79	    await mkdir(dirname(filePath), { recursive: true });
80	
81	    // Write to a temp file in the same directory (so it's on the same
82	    // filesystem as `filePath`, making the rename below atomic rather than a
83	    // copy) and rename it into place. Concurrent PUTs of the same key each
84	    // get their own temp file and race only on the final rename, which the
85	    // filesystem guarantees is all-or-nothing — a concurrent GET can only
86	    // ever observe the fully-old or fully-new content, never a partial write.
87	    const tempPath = `${filePath}${TEMP_FILE_MARKER}${randomUUID()}`;
88	    try {
89	      await writeFile(tempPath, body);
90	      await rename(tempPath, filePath);
91	    } catch (err) {
92	      await unlink(tempPath).catch(() => {});
93	      throw err;
94	    }
95	  } catch (err) {
96	    throw new InvalidKeyError(
97	      `key cannot be written to storage: ${(err as Error).message}`,
98	    );
99	  }
100	
101	  return {
102	    sha256: createHash("sha256").update(body).digest("hex"),
103	    size: body.length,
104	  };
105	}
