108	  dataDir: string,
109	  key: string,
110	): Promise<Buffer | undefined> {
111	  // keyToPath can still throw here (InvalidKeyError) and that's meant to
112	  // propagate to the caller as 400. Once we have a path, though, any
113	  // failure reading it (missing file, or a key whose on-disk form the
114	  // filesystem/OS refuses to stat or open at all - long combining-mark
115	  // runs, astral-plane characters, stray C1/Latin-1 bytes, ...) means
116	  // there is no readable blob at this key, exactly like ENOENT. A key
117	  // that can never be represented on disk could never have been written
118	  // successfully by putBlob either, so "not found" is the accurate answer.
119	  const filePath = keyToPath(dataDir, key);
120	  try {
121	    return await readFile(filePath);
122	  } catch {
123	    return undefined;
124	  }
125	}
