128	  dataDir: string,
129	  key: string,
130	): Promise<boolean> {
131	  // Same reasoning as getBlob: keyToPath's InvalidKeyError still propagates
132	  // as 400, but any OS-level failure removing an existing path is treated
133	  // as "nothing to delete" rather than an uncaught 500.
134	  const filePath = keyToPath(dataDir, key);
135	  try {
136	    await unlink(filePath);
137	    return true;
138	  } catch {
139	    return false;
140	  }
141	}
