143	export async function listBlobs(dataDir: string): Promise<BlobMeta[]> {
144	  const filePaths = await walkFiles(dataDir);
145	  const blobs = await Promise.all(
146	    filePaths.map(async (filePath) => {
147	      const [body, stats] = await Promise.all([
148	        readFile(filePath),
149	        stat(filePath),
150	      ]);
151	      return {
152	        key: toPosixKey(relative(dataDir, filePath)),
153	        size: stats.size,
154	        sha256: createHash("sha256").update(body).digest("hex"),
155	        modified_at: stats.mtime.toISOString(),
156	      };
157	    }),
158	  );
159	
160	  blobs.sort((a, b) => (a.key < b.key ? -1 : a.key > b.key ? 1 : 0));
161	  return blobs;
162	}
